import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X } from 'lucide-react';

const SalesRepDetailsModal = ({ isOpen, onClose, salesRep }) => {
    if (!salesRep) return null;

    return (
        <AnimatePresence>
            {isOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-black/50"
                        onClick={onClose}
                    />
                    <motion.div
                        initial={{ scale: 0.95 }}
                        animate={{ scale: 1 }}
                        exit={{ scale: 0.95 }}
                        className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-lg p-6"
                    >
                        <div className="flex items-center justify-between mb-4">
                            <h2 className="text-xl font-bold">Sales Rep Details</h2>
                            <button onClick={onClose} className="p-1 hover:bg-gray-100 rounded-lg">
                                <X className="h-5 w-5" />
                            </button>
                        </div>
                        <div className="space-y-3">
                            <p><strong>Name:</strong> {salesRep.firstName} {salesRep.lastName}</p>
                            <p><strong>Email:</strong> {salesRep.email}</p>
                            <p><strong>Phone:</strong> {salesRep.phone || 'N/A'}</p>
                            <p><strong>Status:</strong> {salesRep.isActive ? 'Active' : 'Inactive'}</p>
                            {salesRep.commission && (
                                <>
                                    <p><strong>Commission Structure:</strong> {salesRep.commission.structure}</p>
                                    {salesRep.commission.baseSalary > 0 && (
                                        <p><strong>Base Salary:</strong> ${salesRep.commission.baseSalary}</p>
                                    )}
                                    {salesRep.commission.commissionPercentage > 0 && (
                                        <p><strong>Commission %:</strong> {salesRep.commission.commissionPercentage}%</p>
                                    )}
                                </>
                            )}
                        </div>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    );
};

export default SalesRepDetailsModal;
